# name: target_rate_large_feature_gap
# description: Rate of choosing the minimal-feature target in ambiguous utterance trials where the competing matching object has at least 3 more features than the target.
def test_statistic(df):
    sub = df[df['query'] == 'utterance']
    uniques = sub[['objects', 'utterance']].drop_duplicates()
    lookup = {}
    for _, r in uniques.iterrows():
        objs = json.loads(r['objects'])
        utt = int(r['utterance'])
        matches = [i for i, o in enumerate(objs) if o[utt] == 1]
        if len(matches) >= 2:
            counts = [sum(objs[i]) for i in matches]
            min_c = min(counts)
            max_c = max(counts)
            min_matches = [matches[k] for k, c in enumerate(counts) if c == min_c]
            if len(min_matches) == 1 and (max_c - min_c) >= 3:
                lookup[(r['objects'], str(r['utterance']))] = min_matches[0]
    keys = list(zip(sub['objects'], sub['utterance'].astype(str)))
    targets = np.array([lookup.get(k, -1) for k in keys])
    mask = targets != -1
    if not np.any(mask):
        return 0.0
    return float(np.mean(sub['choice'].to_numpy()[mask] == targets[mask]))

# name: prior_empty_singleton_rate_dup_full
# description: Rate of choosing the empty singleton object on mumble trials where the empty object has zero features and the full object has duplicate copies.
def test_statistic(df):
    sub = df[df['query'] == 'prior']
    uniques = sub['objects'].drop_duplicates()
    lookup = {}
    for objs_str in uniques:
        objs = json.loads(objs_str)
        counts = [sum(o) for o in objs]
        obj_tuples = [tuple(o) for o in objs]
        singletons = {i for i, t in enumerate(obj_tuples) if obj_tuples.count(t) == 1}
        max_c = max(counts)
        if min(counts) == 0 and max_c > 0:
            empty_singletons = {i for i, c in enumerate(counts) if c == 0 and i in singletons}
            if len(empty_singletons) == 1 and counts.count(max_c) > 1:
                lookup[objs_str] = list(empty_singletons)[0]
    keys = sub['objects'].tolist()
    is_valid = [k in lookup for k in keys]
    if not any(is_valid):
        return 0.0
    sub_filt = sub[is_valid]
    valid_keys = [k for k in keys if k in lookup]
    choices = sub_filt['choice'].to_numpy()
    targets = np.array([lookup[k] for k in valid_keys])
    return float(np.mean(choices == targets))

